{
  "dashboard": {
    "title": "混沌实验监控",
    "panels": [
      {
        "title": "实验成功率",
        "type": "stat",
        "targets": [
          {
            "expr": "sum(rate(chaos_experiment_total{status=\"success\"}[1h])) / sum(rate(chaos_experiment_total[1h])) * 100"
          }
        ]
      },
      {
        "title": "实验执行时间",
        "type": "graph",
        "targets": [
          {
            "expr": "chaos_experiment_duration_seconds"
          }
        ]
      },
      {
        "title": "受影响 Pod 数量",
        "type": "graph",
        "targets": [
          {
            "expr": "chaos_affected_pods_total"
          }
        ]
      }
    ]
  }
}
